quiz=function(){
 const topics=["All topics",...new Set(quizzes.map(q=>q.topic||"Core"))];
 const levels=["All levels","Beginner","Foundation","Intermediate","Advanced","Professional"];
 const answered=Object.keys(state.quiz||{}).length;
 let h='<div class="hero" style="margin-bottom:18px"><div><span class="eyebrow">FORMATIVE ASSESSMENT</span><h2>Prüfe dein Wissen.</h2><p>Short knowledge checks provide feedback for learning. Exam Practice remains a separate assessment workspace.</p></div><div class="stat"><small>Answered</small><strong>'+answered+'/'+quizzes.length+'</strong></div></div><section class="card"><div class="calc"><div class="field"><label for="vpxQuizTopic">Topic</label><select id="vpxQuizTopic" onchange="vpxFilterQuestions()">'+topics.map(t=>'<option>'+esc(t)+'</option>').join("")+'</select></div><div class="field"><label for="vpxQuizLevel">Level</label><select id="vpxQuizLevel" onchange="vpxFilterQuestions()">'+levels.map(t=>'<option>'+esc(t)+'</option>').join("")+'</select></div><div class="field"><label for="vpxQuizSearch">Search</label><input id="vpxQuizSearch" oninput="vpxFilterQuestions()" placeholder="Search question or topic"></div></div><p class="muted">Choose a topic or level to focus practice. Previously saved answers remain recorded in this browser.</p><div id="vpxQuizList">'+vpxQuestionCards(quizzes,state.quiz,"quiz")+'</div></section>';
 layout("Knowledge Checks",h);
};
function vpxQuestionCards(items,answers,kind){
 return items.map((q,i)=>'<article class="quiz-card vpx-question" data-topic="'+esc(q.topic||"Core")+'" data-level="'+esc(q.level||"Foundation")+'" data-search="'+esc((q.q+" "+(q.topic||"")).toLowerCase())+'"><span class="pill">'+esc(q.topic||"Core")+' · '+esc(q.level||"Foundation")+'</span><p>'+(i+1)+'. '+esc(q.q)+'</p><div class="answers">'+q.a.map((a,j)=>'<button class="answer '+(answers[q.id]!==undefined?(j===q.c?"correct":j===answers[q.id]?"wrong":""):"")+'" '+(answers[q.id]!==undefined?"disabled":"")+' onclick="'+(kind==="exam"?'answerExamExpanded':'answerQuiz')+'(\''+q.id+'\','+j+')">'+String.fromCharCode(65+j)+'. '+esc(a)+'</button>').join("")+'</div>'+(answers[q.id]!==undefined?'<div class="result"><b>'+(answers[q.id]===q.c?"Correct":"Review this answer")+'.</b> '+esc(q.explanation||"Review the related lesson and retry a similar problem.")+'</div>':"")+'</article>').join("");
}
window.vpxFilterQuestions=function(){
 const topic=document.getElementById("vpxQuizTopic")?.value||"All topics",level=document.getElementById("vpxQuizLevel")?.value||"All levels",search=(document.getElementById("vpxQuizSearch")?.value||"").toLowerCase();
 document.querySelectorAll("#vpxQuizList .vpx-question").forEach(e=>{e.hidden=!( (topic==="All topics"||e.dataset.topic===topic) && (level==="All levels"||e.dataset.level===level) && e.dataset.search.includes(search));});
};
