 document.querySelectorAll("#vpxExamList .vpx-question").forEach(e=>{e.hidden=!((topic==="All topics"||e.dataset.topic===topic)&&(level==="All levels"||e.dataset.level===level)&&e.dataset.search.includes(search));});
